import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const host = document.querySelector('#scene-host');
const scene = new THREE.Scene();
scene.background = new THREE.Color('#11162a');
scene.fog = new THREE.FogExp2('#11162a', 0.012);
const camera = new THREE.PerspectiveCamera(42, 1, 0.1, 220);
const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.7));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.22;
host.appendChild(renderer.domElement);

const clamp = THREE.MathUtils.clamp;
const mat = (color, roughness = .72, extra = {}) => new THREE.MeshStandardMaterial({ color, roughness, ...extra });
const materials = {
  ground: mat('#252b3b'), dark: mat('#11162a', .7), gold: mat('#efb951', .38, { metalness: .48 }),
  cream: mat('#fff0cb', .44), red: mat('#e84e72', .5), pink: mat('#ff7b99', .48), blue: mat('#596bd0', .5),
  teal: mat('#55c4bd', .5), purple: mat('#9675d7', .48), wood: mat('#79524e'), black: mat('#161827', .38),
  skin: mat('#f3b99a'), white: mat('#f7f2eb'), green: mat('#4e8d6a'),
};
const sceneRoot = new THREE.Group(); scene.add(sceneRoot);
scene.add(new THREE.HemisphereLight('#a9c5ff', '#25202b', 1.55));
const moonLight = new THREE.DirectionalLight('#c3d6ff', 2.0); moonLight.position.set(-12, 22, 10); moonLight.castShadow = true;
moonLight.shadow.mapSize.set(1024, 1024); moonLight.shadow.camera.left = -22; moonLight.shadow.camera.right = 22; moonLight.shadow.camera.top = 24; moonLight.shadow.camera.bottom = -22; scene.add(moonLight);
const warmFill = new THREE.PointLight('#ff8e69', 38, 34, 2); warmFill.position.set(1, 7, 1); scene.add(warmFill);
const coolFill = new THREE.PointLight('#607aff', 28, 26, 2); coolFill.position.set(-7, 6, -5); scene.add(coolFill);

const ground = new THREE.Mesh(new THREE.PlaneGeometry(180, 180), materials.ground); ground.rotation.x = -Math.PI / 2; ground.position.y = -.16; ground.receiveShadow = true; sceneRoot.add(ground);
const plaza = new THREE.Mesh(new THREE.CircleGeometry(15, 80), mat('#343746')); plaza.rotation.x = -Math.PI / 2; plaza.position.y = -.145; plaza.receiveShadow = true; sceneRoot.add(plaza);
const floorRing = new THREE.Mesh(new THREE.RingGeometry(7.7, 8.1, 72), mat('#a88764', .9)); floorRing.rotation.x = -Math.PI / 2; floorRing.position.y = -.13; sceneRoot.add(floorRing);
const tileRing = new THREE.Mesh(new THREE.RingGeometry(8.7, 8.78, 72), mat('#f1c36d', .56, { emissive: '#774a19', emissiveIntensity: .28 })); tileRing.rotation.x = -Math.PI / 2; tileRing.position.y = -.125; sceneRoot.add(tileRing);

// A deep indigo sky and a scatter of tiny fairground stars.
const starPositions = [];
for (let i = 0; i < 430; i++) {
  const x = (Math.random() - .5) * 130, y = 12 + Math.random() * 48, z = -45 - Math.random() * 95;
  starPositions.push(x, y, z);
}
const starGeo = new THREE.BufferGeometry(); starGeo.setAttribute('position', new THREE.Float32BufferAttribute(starPositions, 3));
const stars = new THREE.Points(starGeo, new THREE.PointsMaterial({ color: '#d9e1ff', size: .13, transparent: true, opacity: .8 })); scene.add(stars);

function box(parent, size, material, pos, rotation = [0, 0, 0], cast = true) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(...size), material); mesh.position.set(...pos); mesh.rotation.set(...rotation); mesh.castShadow = cast; mesh.receiveShadow = true; parent.add(mesh); return mesh;
}
function cylinder(parent, radiusTop, radiusBottom, height, material, pos, radial = 16, open = false) {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radiusTop, radiusBottom, height, radial, 1, open), material);
  mesh.position.set(...pos); mesh.castShadow = true; mesh.receiveShadow = true; parent.add(mesh); return mesh;
}
function sphere(parent, radius, material, pos, scale = [1, 1, 1], width = 12, height = 8) {
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(radius, width, height), material); mesh.position.set(...pos); mesh.scale.set(...scale); mesh.castShadow = true; parent.add(mesh); return mesh;
}
function lineBetween(parent, a, b, radius, material, radial = 6) {
  const start = new THREE.Vector3(...a), end = new THREE.Vector3(...b), delta = end.clone().sub(start);
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, delta.length(), radial), material);
  mesh.position.copy(start.add(end).multiplyScalar(.5)); mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), delta.normalize()); mesh.castShadow = true; parent.add(mesh); return mesh;
}
function emissiveMaterial(color, power = 2.5) { return new THREE.MeshStandardMaterial({ color, emissive: color, emissiveIntensity: power, roughness: .32 }); }

// Carousel platform and illuminated loading deck.
const platform = cylinder(sceneRoot, 7.3, 7.5, .42, mat('#4c3b46', .56), [0, .1, 0], 64);
const platformTrim = cylinder(sceneRoot, 7.5, 7.5, .12, materials.gold, [0, .32, 0], 64);
const platformTop = cylinder(sceneRoot, 7.24, 7.24, .12, mat('#e7d2b7', .85), [0, .39, 0], 64);
const deck = new THREE.Mesh(new THREE.CylinderGeometry(5.35, 5.35, .08, 64), mat('#c5a995')); deck.position.y = .49; deck.receiveShadow = true; sceneRoot.add(deck);
for (let i = 0; i < 24; i++) {
  const a = i * Math.PI * 2 / 24, r = 7.34;
  const bulb = sphere(sceneRoot, .105, emissiveMaterial(i % 2 ? '#ffd06b' : '#ff7593', 2), [Math.cos(a) * r, .42, Math.sin(a) * r], [1, .7, 1], 8, 6);
  bulb.userData.bulb = true;
}
// Central mast, bracing, and a broad striped canopy.
cylinder(sceneRoot, .62, .83, .95, materials.black, [0, .86, 0], 24);
cylinder(sceneRoot, .42, .48, 7.35, mat('#e5dfd6', .32, { metalness: .24 }), [0, 4.95, 0], 24);
cylinder(sceneRoot, .5, .64, .38, materials.gold, [0, 1.27, 0], 24);
cylinder(sceneRoot, .22, .38, .45, materials.red, [0, 8.55, 0], 20);
for (let i = 0; i < 8; i++) {
  const a = i * Math.PI / 4;
  lineBetween(sceneRoot, [0, 1.55, 0], [Math.cos(a) * 5.05, 8.48, Math.sin(a) * 5.05], .055, materials.gold, 8);
}
const canopyBase = cylinder(sceneRoot, 4.72, 4.72, .24, materials.red, [0, 8.55, 0], 48);
cylinder(sceneRoot, 4.8, 4.8, .13, materials.gold, [0, 8.44, 0], 48);
const roof = new THREE.Group(); sceneRoot.add(roof);
for (let i = 0; i < 16; i++) {
  const stripe = new THREE.Mesh(new THREE.ConeGeometry(4.62, 1.32, 1, 1, false, i * Math.PI * 2 / 16, Math.PI * 2 / 16), i % 2 ? materials.cream : materials.red);
  stripe.position.y = 9.18; stripe.castShadow = true; stripe.receiveShadow = true; roof.add(stripe);
}
const roofBand = cylinder(sceneRoot, 4.65, 4.65, .19, mat('#f0d7b6'), [0, 8.64, 0], 48);
cylinder(sceneRoot, 1.04, 1.04, .1, materials.gold, [0, 9.89, 0], 24);
const crown = sphere(sceneRoot, .34, emissiveMaterial('#ffd166', 2), [0, 10.1, 0], [1, 1.25, 1], 16, 10);

// Rotating swing assembly. Arms, hanging chains, two-seat chairs and tiny guests.
const rotor = new THREE.Group(); sceneRoot.add(rotor);
cylinder(rotor, .66, .7, .28, materials.gold, [0, 8.28, 0], 24);
const swingData = [];
const riderMats = [materials.blue, materials.teal, materials.purple, materials.red, materials.green, materials.cream];
const chainMat = mat('#e7d5ad', .32, { metalness: .55 });
for (let i = 0; i < 12; i++) {
  const a = i * Math.PI * 2 / 12;
  const anchor = new THREE.Vector3(Math.cos(a) * 2.22, 8.21, Math.sin(a) * 2.22);
  lineBetween(rotor, [0, 8.2, 0], [anchor.x, anchor.y, anchor.z], .095, materials.gold, 8);
  const chain = cylinder(rotor, .025, .025, 1, chainMat, [0, 0, 0], 6);
  const chair = new THREE.Group(); rotor.add(chair);
  // Small ornate single swing chair.
  box(chair, [.94, .13, .7], i % 2 ? materials.blue : materials.red, [0, 0, 0]);
  box(chair, [.13, .56, .68], materials.gold, [0, .31, -.32]);
  box(chair, [.08, .1, .58], materials.cream, [.49, .05, 0]);
  box(chair, [.08, .1, .58], materials.cream, [-.49, .05, 0]);
  // Seated passenger: body, head, hair, legs and little shoes.
  const clothes = riderMats[i % riderMats.length];
  sphere(chair, .23, clothes, [0, .48, .04], [.82, 1.12, .78], 10, 8);
  sphere(chair, .16, materials.skin, [0, .82, .02], [1, 1, 1], 10, 8);
  sphere(chair, .165, mat(i % 3 ? '#332a32' : '#6a3b32'), [0, .88, -.015], [1.01, .58, 1.02], 10, 6);
  for (const side of [-1, 1]) {
    const arm = sphere(chair, .075, clothes, [side * .23, .56, -.09], [1, 1.45, 1], 8, 6); arm.rotation.z = side * -.25;
    box(chair, [.16, .08, .28], mat('#f7edda'), [side * .16, -.09, .24], [-.42, 0, 0]);
  }
  swingData.push({ a, anchor, chain, chair, phase: i * .29 });
}
const canopyBulbs = [];
for (let i = 0; i < 32; i++) {
  const a = i * Math.PI * 2 / 32;
  const bulb = sphere(sceneRoot, .11, emissiveMaterial(i % 3 ? '#ffe08a' : '#ff7193', 2), [Math.cos(a) * 4.48, 8.53, Math.sin(a) * 4.48], [1, 1, 1], 8, 6);
  bulb.userData.index = i; canopyBulbs.push(bulb);
}

// Fairground fencing around the deck, entry gate and queue lanes.
const fenceMat = mat('#f3d9ae', .45);
for (let i = 0; i < 28; i++) {
  const a = i * Math.PI * 2 / 28, r = 7.72;
  if (Math.cos(a) > .84 && Math.abs(Math.sin(a)) < .48) continue;
  const x = Math.cos(a) * r, z = Math.sin(a) * r;
  cylinder(sceneRoot, .08, .1, .9, fenceMat, [x, .55, z], 8);
  sphere(sceneRoot, .1, materials.gold, [x, 1.02, z], [1, .55, 1], 8, 6);
}
for (const side of [-1, 1]) {
  lineBetween(sceneRoot, [side * 5.1, .64, 5.85], [side * 5.1, .64, 8.1], .045, materials.red, 6);
  for (let i = 0; i < 4; i++) cylinder(sceneRoot, .04, .04, .7, fenceMat, [side * 5.1, .58, 5.9 + i * .66], 6);
}
// A glowing entrance arch.
for (const side of [-1, 1]) cylinder(sceneRoot, .13, .16, 2.25, materials.gold, [side * 1.5, 1.25, 7.3], 12);
box(sceneRoot, [3.25, .48, .23], materials.red, [0, 2.44, 7.3]);
box(sceneRoot, [2.95, .28, .25], materials.black, [0, 2.46, 7.15]);

// Decorative ticket booths with striped awnings, placed at the edges of the fairground.
function makeBooth(x, z, title, tint) {
  const g = new THREE.Group(); g.position.set(x, 0, z); sceneRoot.add(g);
  box(g, [3.2, 2.25, 2.15], mat('#453743'), [0, 1.15, 0]);
  box(g, [3.05, .86, .16], mat('#211d2b'), [0, 1.45, 1.1]);
  box(g, [3.55, .19, 2.45], materials.gold, [0, 2.33, 0]);
  for (let j = 0; j < 7; j++) {
    box(g, [.5, .33, 2.42], j % 2 ? materials.cream : tint, [-1.5 + j * .5, 2.58, 0]);
  }
  box(g, [1.7, .55, .12], mat('#151629'), [0, 3.02, 0]);
  const canvas = document.createElement('canvas'); canvas.width = 512; canvas.height = 128;
  const ctx = canvas.getContext('2d'); ctx.fillStyle = '#17172b'; ctx.fillRect(0, 0, 512, 128);
  ctx.font = 'bold 68px Arial'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.fillStyle = title === 'TICKETS' ? '#ffd16e' : '#ff86a0'; ctx.shadowColor = ctx.fillStyle; ctx.shadowBlur = 18; ctx.fillText(title, 256, 68);
  const signMat = new THREE.MeshBasicMaterial({ map: new THREE.CanvasTexture(canvas), transparent: false });
  const sign = new THREE.Mesh(new THREE.PlaneGeometry(1.58, .38), signMat); sign.position.set(0, 3.02, .071); g.add(sign);
  for (let i = 0; i < 6; i++) sphere(g, .07, emissiveMaterial('#ffe18a', 1.7), [-1.25 + i * .5, 2.32, 1.23], [1, 1, 1], 8, 6);
  return g;
}
makeBooth(-11, -1.5, 'TICKETS', materials.blue);
makeBooth(11, -2.5, 'SÜSSES', materials.red);

// Distant fairground bulbs and low silhouette stalls add depth to the night scene.
for (let i = 0; i < 9; i++) {
  const x = -17 + i * 4.25, z = -13 - (i % 2) * 2;
  box(sceneRoot, [3.1, 1.35, 2], i % 2 ? mat('#4b3643') : mat('#29374a'), [x, .68, z]);
  box(sceneRoot, [3.55, .24, 2.45], i % 2 ? materials.red : materials.blue, [x, 1.48, z]);
  const glow = new THREE.PointLight(i % 2 ? '#ff8b76' : '#68bde7', 9, 7, 2); glow.position.set(x, 2, z + 1.1); sceneRoot.add(glow);
}
// Warm hanging festoon strings over the midway.
const festoon = new THREE.Group(); sceneRoot.add(festoon);
const strand = new THREE.CatmullRomCurve3([new THREE.Vector3(-15, 7, -7), new THREE.Vector3(-8, 5.5, -9), new THREE.Vector3(0, 5.2, -8), new THREE.Vector3(8, 5.5, -9), new THREE.Vector3(15, 7, -7)]);
const wire = new THREE.Mesh(new THREE.TubeGeometry(strand, 40, .025, 5, false), mat('#252738')); festoon.add(wire);
for (let i = 0; i < 21; i++) {
  const p = strand.getPoint(i / 20);
  const b = sphere(festoon, .095, emissiveMaterial(i % 3 ? '#ffd170' : '#ff83a0', 2.1), [p.x, p.y - .12, p.z], [1, 1, 1], 8, 6);
  if (i % 4 === 1) { const light = new THREE.PointLight('#ffc876', 2.4, 5, 2); light.position.copy(b.position); festoon.add(light); }
}

// Little arrow and glowing operator sign at the entrance.
const arrow = new THREE.Mesh(new THREE.ConeGeometry(.22, .42, 4), emissiveMaterial('#ffd166', 1.5)); arrow.rotation.z = Math.PI; arrow.position.set(0, 3.2, 7.31); sceneRoot.add(arrow);

// Orbit camera: drag the scene, scroll to zoom.
let azimuth = .63, elevation = .31, distance = 25.8, dragging = false, prevX = 0, prevY = 0;
const lookAt = new THREE.Vector3(0, 4.45, 0);
function updateCamera() {
  const horizontal = Math.cos(elevation) * distance;
  camera.position.set(Math.sin(azimuth) * horizontal, lookAt.y + Math.sin(elevation) * distance, Math.cos(azimuth) * horizontal);
  camera.lookAt(lookAt);
}
updateCamera();
renderer.domElement.addEventListener('pointerdown', e => { dragging = true; prevX = e.clientX; prevY = e.clientY; renderer.domElement.setPointerCapture(e.pointerId); renderer.domElement.style.cursor = 'grabbing'; });
renderer.domElement.addEventListener('pointermove', e => {
  if (!dragging) return;
  azimuth -= (e.clientX - prevX) * .006; elevation = clamp(elevation + (e.clientY - prevY) * .004, .08, .78); prevX = e.clientX; prevY = e.clientY; updateCamera();
});
renderer.domElement.addEventListener('pointerup', () => { dragging = false; renderer.domElement.style.cursor = 'grab'; });
renderer.domElement.addEventListener('pointercancel', () => { dragging = false; renderer.domElement.style.cursor = 'grab'; });
renderer.domElement.addEventListener('wheel', e => { distance = clamp(distance + e.deltaY * .018, 17, 36); updateCamera(); }, { passive: true });
renderer.domElement.style.cursor = 'grab';

function resize() {
  const w = host.clientWidth, h = host.clientHeight;
  if (!w || !h) return;
  camera.aspect = w / h;
  camera.fov = w < 600 ? 49 : 42;
  camera.updateProjectionMatrix(); renderer.setSize(w, h, false);
}
window.addEventListener('resize', resize); resize();

// Operator console and ride cycle.
const $ = selector => document.querySelector(selector);
const startButton = $('#start-button'), stopButton = $('#stop-button'), speedSlider = $('#speed-slider');
const statusText = $('#ride-status'), phaseTime = $('#phase-time'), startLabel = $('#start-label'), startSub = $('#start-sub');
const occupancyValue = $('#occupancy-value'), occupancyLabel = $('#occupancy-label'), occupancyRing = $('.occupancy-ring');
const speedValue = $('#speed-value'), toast = $('#toast');
let speedSetting = Number(speedSlider.value) / 100;
let spinVelocity = 0, ridePhase = 'ready', phaseRemaining = 0, elapsed = 0, ridersOnboard = 0;
let lightsOn = true, earnings = 1240, ridersToday = 186, toastTimer = 0;
const phaseConfig = { boarding: 4, running: 29, braking: 3.2, unloading: 3.5 };
const numberFormat = new Intl.NumberFormat('de-DE');

function showToast(message) {
  toast.textContent = message; toast.classList.add('show'); window.clearTimeout(toastTimer);
  toastTimer = window.setTimeout(() => toast.classList.remove('show'), 2200);
}
function setPhase(next) {
  ridePhase = next;
  phaseRemaining = phaseConfig[next] || 0;
  const active = next !== 'ready';
  startButton.disabled = active;
  stopButton.disabled = !['boarding', 'running'].includes(next);
  $('.ride-status').classList.toggle('running', next === 'running' || next === 'braking');
  if (next === 'ready') {
    statusText.textContent = 'BETRIEBSBEREIT'; phaseTime.textContent = '—';
    startLabel.textContent = 'Fahrt starten'; startSub.textContent = '12 Gäste warten';
    ridersOnboard = 0; updateOccupancy();
  } else if (next === 'boarding') {
    statusText.textContent = 'GÄSTE STEIGEN EIN'; startLabel.textContent = 'Gäste steigen ein'; startSub.textContent = 'Bitte kurz warten …';
  } else if (next === 'running') {
    statusText.textContent = 'FAHRT LÄUFT'; startLabel.textContent = 'Fahrt läuft'; startSub.textContent = 'Viel Spaß an Bord!';
    ridersOnboard = 12; updateOccupancy();
    showToast('✦ 12 Fahrgäste an Bord — gute Fahrt!');
  } else if (next === 'braking') {
    statusText.textContent = 'WIRD ABGEBREMST'; startLabel.textContent = 'Fahrt klingt aus'; startSub.textContent = 'Sicherheitsbremse aktiv';
    showToast('Fahrt wird sicher abgebremst …');
  } else if (next === 'unloading') {
    statusText.textContent = 'AUSSTIEG'; startLabel.textContent = 'Bitte aussteigen'; startSub.textContent = 'Gleich geht’s weiter';
    ridersOnboard = 0; updateOccupancy();
  }
  if (next !== 'ready') phaseTime.textContent = `${Math.ceil(phaseRemaining)}s`;
}
function updateOccupancy() {
  const pct = Math.round(ridersOnboard / 12 * 100);
  occupancyValue.textContent = pct; occupancyRing.style.setProperty('--progress', `${pct * 3.6}deg`);
  occupancyLabel.textContent = ridersOnboard ? `${ridersOnboard} von 12 Gästen` : 'Bereit zum Einsteigen';
  startSub.textContent = ridePhase === 'ready' ? '12 Gäste warten' : startSub.textContent;
}
function finishRide() {
  earnings += 48; ridersToday += 12;
  $('#earnings').textContent = `€ ${numberFormat.format(earnings)}`;
  $('#riders-today').textContent = numberFormat.format(ridersToday);
  showToast('Fahrt beendet · +€ 48 eingenommen');
  setPhase('ready');
}
function beginRide() {
  if (ridePhase !== 'ready') return;
  setPhase('boarding');
}
function brakeRide() {
  if (ridePhase === 'boarding') { setPhase('unloading'); return; }
  if (ridePhase === 'running') setPhase('braking');
}
startButton.addEventListener('click', beginRide);
stopButton.addEventListener('click', brakeRide);
speedSlider.addEventListener('input', () => {
  speedSetting = Number(speedSlider.value) / 100;
  speedValue.textContent = speedSlider.value;
  const pct = (Number(speedSlider.value) - 30) / 70 * 100;
  speedSlider.style.background = `linear-gradient(90deg,#ff7894 0%,#ff7894 ${pct}%,#ffffff22 ${pct}%,#ffffff22 100%)`;
});
$('#lights-button').addEventListener('click', e => {
  lightsOn = !lightsOn; e.currentTarget.classList.toggle('active', lightsOn);
  e.currentTarget.setAttribute('aria-label', lightsOn ? 'Lichter ausschalten' : 'Lichter einschalten');
  showToast(lightsOn ? '✦ Fahrgeschäftslichter eingeschaltet' : 'Fahrgeschäftslichter ausgeschaltet');
});
window.addEventListener('keydown', e => {
  if (e.code === 'Space' && !e.repeat && !['INPUT', 'BUTTON'].includes(document.activeElement.tagName)) {
    e.preventDefault(); if (ridePhase === 'ready') beginRide(); else brakeRide();
  }
  if (e.key === 'Escape') brakeRide();
});

const clock = new THREE.Clock();
function animate() {
  requestAnimationFrame(animate);
  const dt = Math.min(clock.getDelta(), .05); elapsed += dt;
  if (ridePhase !== 'ready') {
    phaseRemaining = Math.max(0, phaseRemaining - dt);
    phaseTime.textContent = `${Math.ceil(phaseRemaining)}s`;
    if (phaseRemaining <= 0) {
      if (ridePhase === 'boarding') setPhase('running');
      else if (ridePhase === 'running') setPhase('braking');
      else if (ridePhase === 'braking') setPhase('unloading');
      else if (ridePhase === 'unloading') finishRide();
    }
  }
  const targetSpin = ridePhase === 'running' ? (.22 + speedSetting * .83) : 0;
  const ramp = ridePhase === 'braking' ? 1.35 : (ridePhase === 'running' ? .4 : .85);
  spinVelocity = THREE.MathUtils.damp(spinVelocity, targetSpin, ramp, dt);
  rotor.rotation.y -= spinVelocity * dt;
  const swing = clamp(spinVelocity / 1.05, 0, 1);
  for (const item of swingData) {
    const angle = item.a + Math.sin(elapsed * 1.7 + item.phase) * .025 * swing;
    const radius = 2.85 + swing * 1.24;
    const x = Math.cos(angle) * radius, z = Math.sin(angle) * radius;
    const y = 5.05 + swing * .2 + Math.sin(elapsed * 2 + item.phase) * .045 * swing;
    item.chair.position.set(x, y, z); item.chair.rotation.y = angle - Math.PI / 2;
    const end = new THREE.Vector3(x, y + .14, z), delta = end.clone().sub(item.anchor);
    item.chain.position.copy(item.anchor).add(end).multiplyScalar(.5);
    item.chain.scale.y = delta.length();
    item.chain.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), delta.normalize());
  }
  roof.rotation.y = Math.sin(elapsed * .17) * .015;
  crown.rotation.y += dt * .34;
  arrow.position.y = 3.2 + Math.sin(elapsed * 2.3) * .08;
  canopyBulbs.forEach((bulb, i) => {
    const power = lightsOn ? (2 + 1.2 * (Math.sin(elapsed * 4.2 + i * .8) * .5 + .5)) : .12;
    bulb.material.emissiveIntensity = power;
  });
  sceneRoot.traverse(object => {
    if (object.userData.bulb) object.material.emissiveIntensity = lightsOn ? 1.6 + Math.sin(elapsed * 3 + object.position.x) * .35 : .08;
  });
  renderer.render(scene, camera);
}
animate();

